def ichol(A):
    n = len(A)
    L = np.zeros((n, n))
    for i in range(n):
        for j in range(i+1):
            s = sum(L[i,k]*L[j,k] for k in range(j))
            if i == j:
                L[i,i] = np.sqrt(max(A[i,i] - s, 0)) if A[i,i] > 0 else 0
