def n_tangle(psi):
    sigma_y = np.array([[0, -1j], [1j, 0]])
    if len(psi) == 2:
        return abs(np.dot(psi.conj(), tensor_product(sigma_y, psi)))**2
    elif len(psi) % 2 == 0:
        mid = len(psi) // 2
        return abs(np.dot(psi.conj(), tensor_product(n_tangle(psi[:mid]), n_tangle(psi[mid:]))))**2
