import numpy as np

def U_i(r, sigma, epsilon):
    return 4 * epsilon * ((sigma / r) ** 12 - (sigma / r) ** 6)

def U_system(positions, sigma, epsilon):
    N = len(positions)
    E = 0.0
    for i in range(N):
        for j in range(i+1, N):
            r = np.linalg.norm(positions[i] - positions[j])
            E += U_i(r, sigma, epsilon)
    return E / 2

def MC(sigma, epsilon, T, init_positions, MC_steps, dispSize):
    beta = 1.0 / T
    N = len(init_positions)
    E_trace = np.zeros(MC_steps + 1)  # Add one to accommodate step 0 energy

    for step in range(MC_steps):
        i = np.random.randint(N)
        new_position = init_positions[i] + np.random.normal(0, dispSize, 3)
        new_energy = U_system(np.vstack([init_positions[:i], new_position]), sigma, epsilon)

        if step == 0 or np.random.rand() < min(1, np.exp(-beta * (new_energy - E_trace[step]))):
            init_positions[i] = new_position
            E_trace[step + 1] = new_energy

    return E_trace[1:]  # Remove the initial energy value at index 0

